"""Randomised end-to-end oracle comparison for the campaign pipeline.

The oracle below is written directly from PROTOCOL.md and shares no code with
the package: it numbers the harness, recovers values, orders modules and
declarations, evaluates the pipe attestation, and minimises preparations with
a label-Dijkstra that compares (cost, length, commands) tuples literally.
"""
import base64, heapq, json, random, struct, sys
sys.path.insert(0, '.')
import kit


# --------------------------------------------------------------------------- #
# oracle: layout
# --------------------------------------------------------------------------- #

def width_of(tdef):
    kind = tdef["kind"]
    if kind in ("bool", "char"):
        return 1
    if kind == "enum":
        return 4
    bits = tdef["bits"]
    return 1 if bits <= 8 else 2 if bits <= 16 else 4 if bits <= 32 else 8


def limit_of(tdef):
    return 1 << tdef["bits"]


def oracle_layout(types, module, has_pipes):
    slots = []
    counter = [0]

    def walk(tname, path):
        tdef = types[tname]
        kind = tdef["kind"]
        if kind == "alias":
            return walk(tdef["target"], path)
        index = counter[0]
        counter[0] += 1
        if kind in ("bool", "char", "int", "enum"):
            slots.append(("x%d" % index, path, width_of(tdef), kind, tdef))
        elif kind == "string":
            for i in range(tdef["maxsize"]):
                j = counter[0]
                counter[0] += 1
                slots.append(("x%d" % j, path + [i], 1, "char", None))
        elif kind == "array":
            for i in range(tdef["size"]):
                walk(tdef["element"], path + [i])
        elif kind == "struct":
            for fname, ename in tdef["fields"]:
                walk(ename, path + [fname])

    for pname, tname in module["params"]:
        walk(tname, [pname])
    rname, rtname = module["result"]
    if types[rtname]["kind"] != "void":
        walk(rtname, [rname])
    variables = counter[0]
    flag = None
    if has_pipes:
        flag = "x%d" % variables
        variables += 1
    return slots, flag, variables


def oracle_declarations(types, order, modules):
    result = []
    done = set()

    def walk(tname):
        tdef = types[tname]
        if tdef["name"] in done:
            return
        kind = tdef["kind"]
        if kind in ("bool", "char", "int", "string", "void", "array"):
            if kind == "array":
                done.add(tdef["name"])
                walk(tdef["element"])
            return
        if kind == "enum":
            done.add(tdef["name"])
            result.append(tdef["name"])
            return
        done.add(tdef["name"])
        if kind == "alias":
            walk(tdef["target"])
        else:
            for fname, ename in tdef["fields"]:
                walk(ename)
        result.append(tdef["name"])

    for name in order:
        module = modules[name]
        for pname, tname in module["params"]:
            walk(tname)
        walk(module["result"][1])
    return result


def oracle_order(modules, calls, pipes, root):
    prereqs = {}
    for name in modules:
        prereqs.setdefault(name, set())
    for caller, callee in calls:
        prereqs.setdefault(callee, set())
        prereqs.setdefault(caller, set())
        prereqs[caller].add(callee)
    for pipe in pipes:
        prereqs.setdefault(pipe["filter"], set())
        prereqs.setdefault(pipe["target"], set())
        prereqs[pipe["target"]].add(pipe["filter"])
    seen = {root}
    stack = [root]
    while stack:
        node = stack.pop()
        for prereq in prereqs[node]:
            if prereq not in seen:
                seen.add(prereq)
                stack.append(prereq)
    order = []
    remaining = set(seen)
    while remaining:
        ready = sorted(n for n in remaining if not (prereqs[n] & seen - set(order)) - set(order))
        ready = sorted(n for n in remaining if prereqs[n] <= set(order))
        order.append(ready[0])
        remaining.discard(ready[0])
    return order


def oracle_applications(pipes, filters, root):
    """Return the list of filter names applied (transitively) at the root."""
    out = []

    def walk(target):
        for pipe in pipes:
            if pipe["target"] == target:
                out.append(pipe["filter"])
                walk(pipe["filter"])
    walk(root)
    return out


# --------------------------------------------------------------------------- #
# oracle: preparation
# --------------------------------------------------------------------------- #

def oracle_prepare(machine, enabled, target):
    states = machine["states"]
    index = {name: i for i, name in enumerate(states)}
    start = index[machine["initial"]]
    goal = index[target]
    out = [[] for _ in states]
    for tid, t in enumerate(machine["transitions"]):
        if enabled[tid]:
            out[index[t["from"]]].append((index[t["to"]], t["cost"], t["command"]))
    label = [None] * len(states)
    label[start] = (0, 0, ())
    heap = [(0, 0, (), start)]
    while heap:
        cost, hops, seq, node = heapq.heappop(heap)
        if (cost, hops, seq) != label[node]:
            continue
        for successor, weight, command in out[node]:
            candidate = (cost + weight, hops + 1, seq + (command,))
            if label[successor] is None or candidate < label[successor]:
                label[successor] = candidate
                heapq.heappush(heap, candidate + (successor,))
    if label[goal] is None:
        return None
    return list(label[goal][2]), label[goal][0]


# --------------------------------------------------------------------------- #
# generation
# --------------------------------------------------------------------------- #

class Gen:
    def __init__(self, rng):
        self.rng = rng
        self.types = {}
        self.order = []

    def add(self, tdef):
        self.types[tdef["name"]] = tdef
        self.order.append(tdef["name"])

    def fresh(self, prefix):
        return "%s%d" % (prefix, len(self.order))

    def make(self, depth=0):
        rng = self.rng
        kinds = ["bool", "char", "int", "string", "enum", "array", "struct", "alias"]
        for kind in kinds:
            if kind in ("array", "struct", "alias") and (depth >= 3 or not self.order):
                continue
            name = self.fresh(kind[0].upper())
            if kind == "bool":
                self.add({"name": name, "kind": "bool"})
            elif kind == "char":
                self.add({"name": name, "kind": "char"})
            elif kind == "int":
                self.add({"name": name, "kind": "int", "bits": rng.choice([1, 7, 8, 9, 16, 17, 32, 33, 64])})
            elif kind == "string":
                self.add({"name": name, "kind": "string", "maxsize": rng.choice([0, 1, 3, 5])})
            elif kind == "enum":
                self.add({"name": name, "kind": "enum",
                          "values": ["v%d" % i for i in range(rng.randint(1, 4))]})
            elif kind == "array":
                element = rng.choice(self.order)
                self.add({"name": name, "kind": "array", "element": element,
                          "size": rng.choice([0, 1, 2, 3])})
            elif kind == "struct":
                fields = [[f"f{i}", rng.choice(self.order)] for i in range(rng.randint(0, 3))]
                self.add({"name": name, "kind": "struct", "fields": fields})
            else:
                target = rng.choice(self.order)
                if self.depth(target) >= 4:
                    continue
                self.add({"name": name, "kind": "alias", "target": target})
            return name
        name = self.fresh("P")
        self.add({"name": name, "kind": "bool"})
        return name

    def depth(self, tname, seen=None):
        seen = seen or set()
        tdef = self.types[tname]
        kind = tdef["kind"]
        if kind in ("alias",):
            return 1 + self.depth(tdef["target"], seen)
        if kind == "array":
            return 1 + self.depth(tdef["element"], seen)
        if kind == "struct":
            return 1 + max([0] + [self.depth(e, seen) for _, e in tdef["fields"]])
        return 0

    def pick(self):
        return self.rng.choice(self.order)

    def value(self, tname):
        """Return (json_value, {path_tuple: (kind, int_value, width)})."""
        rng = self.rng
        tdef = self.types[tname]
        kind = tdef["kind"]
        if kind == "alias":
            return self.value(tdef["target"])
        if kind == "void":
            return None, {}
        if kind == "bool":
            bit = rng.randint(0, 1)
            return bool(bit), {(): ("bool", bit, 1)}
        if kind == "char":
            cp = rng.choice([0, 65, 97, 255, 32, 126])
            return chr(cp), {(): ("char", cp, 1)}
        if kind == "int":
            v = rng.randint(0, limit_of(tdef) - 1)
            return v, {(): ("int", v, width_of(tdef))}
        if kind == "enum":
            i = rng.randrange(len(tdef["values"]))
            return tdef["values"][i], {(): ("enum", i, 4)}
        if kind == "string":
            chars = [rng.choice([0, 65, 66, 97, 255, 0]) for _ in range(tdef["maxsize"])]
            text = ""
            for cp in chars:
                if cp == 0:
                    break
                text += chr(cp)
            leaves = {(i,): ("char", cp, 1) for i, cp in enumerate(chars)}
            return text, leaves
        if kind == "array":
            items = []
            leaves = {}
            for i in range(tdef["size"]):
                value, sub = self.value(tdef["element"])
                items.append(value)
                for path, leaf in sub.items():
                    leaves[(i,) + path] = leaf
            return items, leaves
        if kind == "struct":
            record = {}
            leaves = {}
            for fname, ename in tdef["fields"]:
                value, sub = self.value(ename)
                record[fname] = value
                for path, leaf in sub.items():
                    leaves[(fname,) + path] = leaf
            return record, leaves
        raise AssertionError(kind)
